<?php $page_title='Reportes'; require 'header.php'; $rows=[];if($pdo){$rows=$pdo->query("SELECT x.fecha,COUNT(*) total,SUM(x.estado='Presente') presentes,SUM(x.estado='Ausente') ausentes,SUM(x.estado='Tardanza') tardanzas FROM asistencias x GROUP BY x.fecha ORDER BY x.fecha DESC")->fetchAll();} ?><div class="d-flex justify-content-between align-items-center mb-4 no-print"><div><h1 class="h3 fw-bold">Reportes</h1><p class="text-secondary">Resumen imprimible de asistencia.</p></div><button class="btn btn-dark" onclick="window.print()"><i class="fa-solid fa-print me-2"></i>Imprimir / PDF</button></div><div class="card p-4"><div class="print-only mb-4"><h1>KRONO — Reporte de asistencia</h1><p>Sistema de Control de Asistencias 2026</p></div><h2 class="h5">Resumen por fecha</h2><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Fecha</th><th>Total</th><th>Presentes</th><th>Ausentes</th><th>Tardanzas</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['fecha'])?></td><td><?=e($r['total'])?></td><td><?=e($r['presentes'])?></td><td><?=e($r['ausentes'])?></td><td><?=e($r['tardanzas'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'footer.php'; ?>
